19. package crypto
20. 
21. import (
22. 	"crypto"
23. 	"crypto/ecdsa"
24. 	"crypto/ed25519"
25. 	"crypto/rsa"
26. 	"errors"
27. 	"fmt"
28. 
29. 	"github.com/lestrrat-go/jwx/jwa"
30. 	"github.com/lestrrat-go/jwx/jwk"
31. 	"github.com/lestrrat-go/jwx/jws"
32. 	"github.com/lestrrat-go/jwx/jwt"
33. 	"github.com/nuts-foundation/nuts-node/crypto/storage"
34. 	"github.com/shengdoushi/base58"
35. )
36. 
37. // ErrUnsupportedSigningKey is returned when an unsupported private key is used to sign. Currently only ecdsa and rsa keys are supported
38. var ErrUnsupportedSigningKey = errors.New("signing key algorithm not supported")
39. 
40. var supportedAlgorithms = []jwa.SignatureAlgorithm{jwa.PS256, jwa.PS384, jwa.PS512, jwa.ES256, jwa.ES384, jwa.ES512}
41. 
42. func isAlgorithmSupported(alg jwa.SignatureAlgorithm) bool {
43. 	for _, curr := range supportedAlgorithms {
44. 		if curr == alg {
45. 			return true
46. 		}
47. 	}
48. 	return false
49. }
50. 
51. // SignJWT creates a signed JWT given a legalEntity and map of claims
52. func (client *Crypto) SignJWT(claims map[string]interface{}, kid string) (token string, err error) {
53. 	privateKey, err := client.Storage.GetPrivateKey(kid)
54. 	if err != nil {
55. 		if errors.Is(err, storage.ErrNotFound) {
56. 			return "", ErrKeyNotFound
57. 		}
58. 		return "", err
59. 	}
60. 	key, err := jwkKey(privateKey)
61. 	if err != nil {
62. 		return "", err
63. 	}
64. 
65. 	if err = key.Set(jwk.KeyIDKey, kid); err != nil {
66. 		return "", err
67. 	}
68. 
69. 	token, err = SignJWT(key, claims, nil)
70. 	return
71. }
72. 
73. func jwkKey(signer crypto.Signer) (key jwk.Key, err error) {
74. 	key, err = jwk.New(signer)
75. 	if err != nil {
76. 		return nil, err
77. 	}
78. 
79. 	switch signer.(type) {
80. 	case *rsa.PrivateKey:
81. 		key.Set(jwk.AlgorithmKey, jwa.PS256)
82. 	case *ecdsa.PrivateKey:
83. 		ecKey := signer.(*ecdsa.PrivateKey)
84. 		var alg jwa.SignatureAlgorithm
85. 		alg, err = ecAlg(ecKey)
86. 		key.Set(jwk.AlgorithmKey, alg)
87. 	default:
88. 		err = errors.New("unsupported signing private key")
89. 	}
90. 	return
91. }
92. 
93. // SignJWT signs claims with the signer and returns the compacted token. The headers param can be used to add additional headers
94. func SignJWT(key jwk.Key, claims map[string]interface{}, headers map[string]interface{}) (token string, err error) {
95. 	var sig []byte
96. 	t := jwt.New()
97. 
98. 	for k, v := range claims {
99. 		if err := t.Set(k, v); err != nil {
100. 			return "", err
101. 		}
102. 	}
103. 	hdr := convertHeaders(headers)
104. 
105. 	sig, err = jwt.Sign(t, jwa.SignatureAlgorithm(key.Algorithm()), key, jws.WithHeaders(hdr))
106. 	token = string(sig)
107. 
108. 	return
109. }
110. 
111. // JWTKidAlg parses a JWT, does not validate it and returns the 'kid' and 'alg' headers
112. func JWTKidAlg(tokenString string) (string, jwa.SignatureAlgorithm, error) {
113. 	j, err := jws.ParseString(tokenString)
114. 	if err != nil {
115. 		return "", "", err
116. 	}
117. 
118. 	if len(j.Signatures()) != 1 {
119. 		return "", "", errors.New("incorrect number of signatures in JWT")
120. 	}
121. 
122. 	sig := j.Signatures()[0]
123. 	hdrs := sig.ProtectedHeaders()
124. 	return hdrs.KeyID(), hdrs.Algorithm(), nil
125. }
126. 
127. // PublicKeyFunc defines a function that resolves a public key based on a kid
128. type PublicKeyFunc func(kid string) (crypto.PublicKey, error)
129. 
130. // ParseJWT parses a token, validates and verifies it.
131. func ParseJWT(tokenString string, f PublicKeyFunc) (jwt.Token, error) {
132. 	kid, alg, err := JWTKidAlg(tokenString)
133. 	if err != nil {
134. 		return nil, err
135. 	}
136. 
137. 	key, err := f(kid)
138. 	if err != nil {
139. 		return nil, err
140. 	}
141. 
142. 	if !isAlgorithmSupported(alg) {
143. 		return nil, fmt.Errorf("token signing algorithm is not supported: %s", alg)
144. 	}
145. 
146. 	return jwt.ParseString(tokenString, jwt.WithVerify(alg, key), jwt.WithValidate(true))
147. }
148. 
149. func SignJWS(payload []byte, protectedHeaders map[string]interface{}, privateKey crypto.Signer) (string, error) {
150. 	headers := jws.NewHeaders()
151. 	for key, value := range protectedHeaders {
152. 		if err := headers.Set(key, value); err != nil {
153. 			return "", fmt.Errorf("unable to set header %s: %w", key, err)
154. 		}
155. 	}
156. 	privateKeyAsJWK, err := jwkKey(privateKey)
157. 	if err != nil {
158. 		return "", err
159. 	}
160. 	// The JWX library is fine with creating a JWK for a private key (including the private exponents), so
161. 	// we want to make sure the `jwk` header (if present) does not (accidentally) contain a private key.
162. 	// That would lead to the node leaking its private key material in the resulting JWS which would be very, very bad.
163. 	if headers.JWK() != nil {
164. 		var jwkAsPrivateKey crypto.Signer
165. 		if err := headers.JWK().Raw(&jwkAsPrivateKey); err == nil {
166. 			// `err != nil` is good in this case, because that means the key is not assignable to crypto.Signer,
167. 			// which is the interface implemented by all private key types.
168. 			return "", errors.New("refusing to sign JWS with private key in JWK header")
169. 		}
170. 	}
171. 	algo := jwa.SignatureAlgorithm(privateKeyAsJWK.Algorithm())
172. 	data, err := jws.Sign(payload, algo, privateKey, jws.WithHeaders(headers))
173. 	if err != nil {
174. 		return "", fmt.Errorf("unable to sign JWS %w", err)
175. 	}
176. 	return string(data), nil
177. }
178. 
179. func convertHeaders(headers map[string]interface{}) (hdr jws.Headers) {
180. 	hdr = jws.NewHeaders()
181. 
182. 	if headers != nil {
183. 		for k, v := range headers {
184. 			hdr.Set(k, v)
185. 		}
186. 	}
187. 	return
188. }
189. 
190. func ecAlg(key *ecdsa.PrivateKey) (alg jwa.SignatureAlgorithm, err error) {
191. 	alg, err = ecAlgUsingPublicKey(key.PublicKey)
192. 	return
193. }
194. 
195. func ecAlgUsingPublicKey(key ecdsa.PublicKey) (alg jwa.SignatureAlgorithm, err error) {
196. 	switch key.Params().BitSize {
197. 	case 256:
198. 		alg = jwa.ES256
199. 	case 384:
200. 		alg = jwa.ES384
201. 	case 521:
202. 		alg = jwa.ES512
203. 	default:
204. 		err = ErrUnsupportedSigningKey
205. 	}
206. 	return
207. }
208. 
209. // SignatureAlgorithm determines the jwa.SigningAlgorithm for ec/rsa/ed25519 keys.
210. func SignatureAlgorithm(key crypto.PublicKey) (jwa.SignatureAlgorithm, error) {
211. 	if key == nil {
212. 		return "", errors.New("no key provided")
213. 	}
214. 
215. 	var ptr interface{}
216. 	switch v := key.(type) {
217. 	case rsa.PrivateKey:
218. 		ptr = &v
219. 	case rsa.PublicKey:
220. 		ptr = &v
221. 	case ecdsa.PrivateKey:
222. 		ptr = &v
223. 	case ecdsa.PublicKey:
224. 		ptr = &v
225. 	default:
226. 		ptr = v
227. 	}
228. 
229. 	switch ptr.(type) {
230. 	case *rsa.PrivateKey:
231. 		return jwa.PS256, nil
232. 	case *rsa.PublicKey:
233. 		return jwa.PS256, nil
234. 	case *ecdsa.PrivateKey:
235. 		sk := ptr.(*ecdsa.PrivateKey)
236. 		return ecAlgUsingPublicKey(sk.PublicKey)
237. 	case *ecdsa.PublicKey:
238. 		pk := ptr.(*ecdsa.PublicKey)
239. 		return ecAlgUsingPublicKey(*pk)
240. 	case ed25519.PrivateKey:
241. 		return jwa.EdDSA, nil
242. 	case ed25519.PublicKey:
243. 		return jwa.EdDSA, nil
244. 	default:
245. 		return "", fmt.Errorf(`invalid key type '%T' for jwk.New`, key)
246. 	}
247. }
248. 
249. // Thumbprint generates a Nuts compatible thumbprint: Base58(SHA256(rfc7638-json))
250. func Thumbprint(key jwk.Key) (string, error) {
251. 	pkHash, err := key.Thumbprint(crypto.SHA256)
252. 	if err != nil {
253. 		return "", err
254. 	}
255. 	return base58.Encode(pkHash[:], base58.BitcoinAlphabet), nil
256. }
257.

