 		Roots:         rootsPool,
 		CurrentTime:   checkTime,
 		KeyUsages:     []x509.ExtKeyUsage{x509.ExtKeyUsageAny},
 	}

 	for _, cert := range chain[1:] {
 		verifyOpts.Intermediates.AddCert(cert)
 	}

