22. // NewTransactionSigner creates a TransactionSigner that signs the transaction using the given key.
23. // The public key is included in the signed transaction if attach == true. If not attached, the `kid` header is added which refers to the ID
24. // of the used key.
25. func NewTransactionSigner(key crypto.Key, attach bool) TransactionSigner {
26. 	return &transactionSigner{
27. 		key:    key,
28. 		attach: attach,
29. 	}
30. }
