32. type transactionSigner struct {
33. 	attach bool
34. 	key    crypto.Key
35. }
36. 
37. func (d transactionSigner) Sign(input UnsignedTransaction, signingTime time.Time) (Transaction, error) {
38. 	// Preliminary sanity checks
39. 	if signingTime.IsZero() {
40. 		return nil, errors.New("signing time is zero")
41. 	}
42. 	if tx, ok := input.(Transaction); ok && !tx.SigningTime().IsZero() {
43. 		return nil, errors.New("transaction is already signed")
44. 	}
45. 
46. 	var key jwk.Key
