1. package x509
2. 
3. import (
4. 	"bytes"
5. 	"crypto/x509"
6. 	"encoding/asn1"
7. 	"encoding/base64"
8. 	"encoding/json"
9. 	"fmt"
10. 	"time"
11. 
12. 	"github.com/lestrrat-go/jwx/jwa"
13. 	"github.com/lestrrat-go/jwx/jws"
14. 	"github.com/lestrrat-go/jwx/jwt"
15. )
16. 
17. // JwtX509Token contains a parsed JWT signed with a x509 certificate.
18. type JwtX509Token struct {
19. 	chain  []*x509.Certificate
20. 	token  jwt.Token
21. 	raw    string
22. 	sigAlg jwa.SignatureAlgorithm
23. }
24. 
25. // JwtX509Validator contains all logic to parse and verify a JwtX509Token.
26. type JwtX509Validator struct {
27. 	roots              []*x509.Certificate
28. 	intermediates      []*x509.Certificate
29. 	allowedSigningAlgs []jwa.SignatureAlgorithm
30. 	crls               CRLGetter
31. }
32. 
33. // generalNames defines the asn1 data structure of the generalNames as defined in rfc5280#section-4.2.1.6
34. type generalNames struct {
35. 	OtherName otherName `asn1:"tag:0"`
36. }
37. 
38. // otherName defines the asn1 data structure of the othername as defined in rfc5280#section-4.2.1.6
39. type otherName struct {
40. 	OID   asn1.ObjectIdentifier
41. 	Value asn1.RawValue `asn1:"tag:0"`
42. }
43. 
44. // subjectAltNameID is the object identifier of the subjectAltName (id-ce 17)
45. var subjectAltNameID = asn1.ObjectIdentifier{2, 5, 29, 17}
46. 
47. // SubjectAltNameOtherNames extracts the SANs as string from the certificate which was used to sign the Jwt.
48. func (j JwtX509Token) SubjectAltNameOtherNames() ([]string, error) {
49. 	leaf := j.chain[0]
50. 	result := []string{}
51. 	for _, ext := range leaf.Extensions {
52. 		if ext.Id.Equal(subjectAltNameID) {
53. 			if len(ext.Value) == 0 {
54. 				continue
55. 			}
56. 
57. 			var otherNames generalNames
58. 			if _, err := asn1.Unmarshal(ext.Value, &otherNames); err != nil {
59. 				return nil, err
60. 			}
61. 			var otherNameStr string
62. 			if _, err := asn1.Unmarshal(otherNames.OtherName.Value.Bytes, &otherNameStr); err != nil {
63. 				return nil, err
64. 			}
65. 			result = append(result, otherNameStr)
66. 		}
67. 	}
68. 	return result, nil
69. }
70. 
71. // NewJwtX509Validator creates a new NewJwtX509Validator.
72. // It accepts root and intermediate certificates to validate the chain.
73. // It accepts a list of valid signature algorithms
74. // It accepts a CRL getter
75. func NewJwtX509Validator(roots, intermediates []*x509.Certificate, allowedSigAlgs []jwa.SignatureAlgorithm, crls CRLGetter) *JwtX509Validator {
76. 	return &JwtX509Validator{
77. 		roots:              roots,
78. 		intermediates:      intermediates,
79. 		allowedSigningAlgs: allowedSigAlgs,
80. 		crls:               crls,
81. 	}
82. }
83. 
84. // Parse attempts to parse a string as a jws. It checks if the x5c header contains at least 1 certificate.
85. // The signature should be signed with the private key of the leaf certificate.
86. // No other validations are performed. Call Verify to verify the auth token.
87. func (validator JwtX509Validator) Parse(rawAuthToken string) (*JwtX509Token, error) {
88. 	// check the cert chain in the jwt
89. 	rawHeader, _, _, err := jws.SplitCompact([]byte(rawAuthToken))
90. 	if err != nil {
91. 		return nil, fmt.Errorf("the jwt should contain out of 3 parts: %w", err)
92. 	}
93. 
94. 	headers := jws.NewHeaders()
95. 	headerStr, _ := base64.RawURLEncoding.DecodeString(string(rawHeader))
96. 	if err = json.Unmarshal(headerStr, headers); err != nil {
97. 		return nil, fmt.Errorf("could not parse jwt headers: %w", err)
98. 	}
99. 
100. 	certsFromHeader := headers.X509CertChain()
101. 	if len(certsFromHeader) == 0 {
102. 		return nil, fmt.Errorf("the jwt x5c field should contain at least 1 certificate")
103. 	}
104. 
105. 	chain, err := validator.parseBase64EncodedCertList(certsFromHeader)
106. 	if err != nil {
107. 		return nil, fmt.Errorf("could not parse certificates from headers: %w", err)
108. 	}
109. 
110. 	certUsedForSigning := chain[0]
111. 
112. 	payload, err := jws.Verify([]byte(rawAuthToken), headers.Algorithm(), certUsedForSigning.PublicKey)
113. 	if err != nil {
114. 		return nil, fmt.Errorf("could not verify jwt signature: %w", err)
115. 	}
116. 
117. 	parsedJwt := jwt.New()
118. 	if err := json.Unmarshal(payload, &parsedJwt); err != nil {
119. 		return nil, fmt.Errorf("could not parse jwt payload: %w", err)
120. 	}
121. 
122. 	return &JwtX509Token{
123. 		chain:  chain,
124. 		token:  parsedJwt,
125. 		raw:    rawAuthToken,
126. 		sigAlg: headers.Algorithm(),
127. 	}, nil
128. }
129. 
130. // parseBase64EncodedCertList makes it convenient to parse an array of base64 certificates into x509.Certificates
131. func (validator JwtX509Validator) parseBase64EncodedCertList(certsFromHeader []string) ([]*x509.Certificate, error) {
132. 	// Parse all the certificates from the header into a chain
133. 	chain := []*x509.Certificate{}
134. 
135. 	for _, certStr := range certsFromHeader {
136. 		rawCert, err := base64.StdEncoding.Strict().DecodeString(certStr)
137. 		if err != nil {
138. 			return nil, fmt.Errorf("could not base64 decode certificate: %w", err)
139. 		}
140. 		cert, err := x509.ParseCertificate(rawCert)
141. 		if err != nil {
142. 			return nil, fmt.Errorf("could not parse certificate: %w", err)
143. 		}
144. 		chain = append(chain, cert)
145. 	}
146. 	return chain, nil
147. }
148. 
149. // nowFunc can be overwritten during tests to return a different time
150. var nowFunc = time.Now
151. 
152. // Verify verifies a JwtX509Token.
153. // It checks the signature algorithm
154. // It verifies if the certificate used to sign the token has a valid chain
155. // It checks the signature of the jst against the provided leaf certificate in the x509 header
156. // It performs additional JWT checks on optional fields like exp, nbf, iat etc.
157. // Note: it does not verifies the extended key usage! This should be performed by hand.
158. func (validator JwtX509Validator) Verify(x509Token *JwtX509Token) error {
159. 	var sigAlgAllowed bool
160. 	for _, allowedAlg := range validator.allowedSigningAlgs {
161. 		if allowedAlg == x509Token.sigAlg {
162. 			sigAlgAllowed = true
163. 			break
164. 		}
165. 	}
166. 	if !sigAlgAllowed {
167. 		return fmt.Errorf("signature algorithm %s is not allowed", x509Token.sigAlg)
168. 	}
169. 
170. 	rawIat, ok := x509Token.token.Get(jwt.IssuedAtKey)
171. 	checkTime, iatCastOk := rawIat.(time.Time)
172. 	if !ok || !iatCastOk {
173. 		return fmt.Errorf("jwt must have an issued at (iat) field")
174. 	}
175. 	leafCert, verifiedChains, err := validator.verifyCertChain(x509Token.chain, checkTime)
176. 	if err != nil {
177. 		return err
178. 	}
179. 
180. 	for _, verifiedChain := range verifiedChains {
181. 		err := validator.checkCertRevocation(verifiedChain)
182. 		if err != nil {
183. 			return err
184. 		}
185. 	}
186. 
187. 	// parse the jwt and verify the jwt signature
188. 	token, err := jwt.ParseString(x509Token.raw, jwt.WithVerify(x509Token.sigAlg, leafCert.PublicKey))
189. 	if err != nil {
190. 		return err
191. 	}
192. 
193. 	// verify the jwt contents such as expiration
194. 	if err := jwt.Validate(token); err != nil {
195. 		return err
196. 	}
197. 
198. 	return nil
199. }
200. 
201. // verifyCertChain tries to find a valid certificate chain for the given JwtX509Token.
202. // It uses the provided roots and intermediates.
203. // If a chain is found, it returns the leaf certificate and the list of valid chains.
204. // A chain should have been valid during the token issued at time.
205. func (validator JwtX509Validator) verifyCertChain(chain []*x509.Certificate, checkTime time.Time) (*x509.Certificate, [][]*x509.Certificate, error) {
206. 	if len(chain) == 0 {
207. 		return nil, nil, fmt.Errorf("JWT x5c field does not contain certificates")
208. 	}
209. 
210. 	rootsPool := x509.NewCertPool()
211. 	for _, cert := range validator.roots {
212. 		rootsPool.AddCert(cert)
213. 	}
214. 	intermediatesPool := x509.NewCertPool()
215. 	for _, cert := range validator.intermediates {
216. 		intermediatesPool.AddCert(cert)
217. 	}
218. 	verifyOpts := x509.VerifyOptions{
219. 		Intermediates: intermediatesPool,
220. 		Roots:         rootsPool,
221. 		CurrentTime:   checkTime,
222. 		KeyUsages:     []x509.ExtKeyUsage{x509.ExtKeyUsageAny},
223. 	}
224. 
225. 	for _, cert := range chain[1:] {
226. 		verifyOpts.Intermediates.AddCert(cert)
227. 	}
228. 
229. 	leafCert := chain[0]
230.

