39. 	if signingTime.IsZero() {
40. 		return nil, errors.New("signing time is zero")
41. 	}
42. 	if tx, ok := input.(Transaction); ok && !tx.SigningTime().IsZero() {
43. 		return nil, errors.New("transaction is already signed")
44. 	}
