56. 	prevsAsString := make([]string, len(input.Previous()))
57. 	for i, prev := range input.Previous() {
58. 		prevsAsString[i] = prev.String()
59. 	}
60. 	normalizedMoment := signingTime.UTC()
61. 	headerMap := map[string]interface{}{
62. 		jws.ContentTypeKey: input.PayloadType(),
63. 		jws.CriticalKey:    []string{signingTimeHeader, versionHeader, previousHeader},
64. 		signingTimeHeader:  normalizedMoment.Unix(),
65. 		previousHeader:     prevsAsString,
66. 		versionHeader:      input.Version(),
