31. // ParseTransaction parses the input as Nuts Network Transaction according to RFC004.
32. func ParseTransaction(input []byte) (Transaction, error) {
33. 	message, err := jws.Parse(input)
34. 	if err != nil {
35. 		return nil, fmt.Errorf(unableToParseTransactionErrFmt, err)
36. 	}
37. 	if len(message.Signatures()) == 0 {
38. 		return nil, transactionValidationError("JWS does not contain any signature")
39. 	} else if len(message.Signatures()) > 1 {
40. 		return nil, transactionValidationError("JWS contains multiple signature")
41. 	}
42. 
43. 	signature := message.Signatures()[0]
44. 	headers := signature.ProtectedHeaders()
45. 
46. 	var steps = []transactionParseStep{
47. 		parseSigningAlgorithm,
48. 		parsePayload,
49. 		parseContentType,
50. 		parseSignatureParams,
51. 		parseSigningTime,
52. 		parseVersion,
53. 		parsePrevious,
54. 	}
55. 
56. 	result := &transaction{}
57. 	result.setData(input)
58. 	for _, step := range steps {
59. 		if err := step(result, headers, message); err != nil {
60. 			return nil, err
61. 		}
62. 	}
63. 	return result, nil
64. }
65. 
66. func transactionValidationError(format string, args ...interface{}) error {
67. 	return fmt.Errorf(transactionNotValidErrFmt, fmt.Errorf(format, args...))
68. }
69. 
70. // transactionParseStep defines a function that parses a part of a JWS, building the internal representation of a transaction.
71. // If an error occurs during parsing or validation it should be returned.
72. type transactionParseStep func(transaction *transaction, headers jws.Headers, message *jws.Message) error
73. 
74. // parseSigningAlgorithm validates whether the signing algorithm is allowed
75. func parseSigningAlgorithm(_ *transaction, headers jws.Headers, _ *jws.Message) error {
76. 	if !isAlgoAllowed(headers.Algorithm()) {
77. 		return transactionValidationError("signing algorithm not allowed: %s", headers.Algorithm())
78. 	}
79. 	return nil
80. }
81. 
82. // parsePayload parses the transaction payload (contents) and sets it
83. func parsePayload(transaction *transaction, _ jws.Headers, message *jws.Message) error {
84. 	payload, err := hash.ParseHex(string(message.Payload()))
85. 	if err != nil {
86. 		return transactionValidationError("invalid payload: %w", err)
87. 	}
88. 	transaction.payload = payload
89. 	return nil
90. }
91. 
92. // parseContentType parses, validates and sets the transaction payload content type.
93. func parseContentType(transaction *transaction, headers jws.Headers, _ *jws.Message) error {
94. 	contentType := headers.ContentType()
95. 	if !ValidatePayloadType(contentType) {
96. 		return transactionValidationError(errInvalidPayloadType.Error())
97. 	}
98. 	transaction.payloadType = contentType
99. 	return nil
100. }
101. 
102. // parseSignatureParams parses, validates and sets the transaction signing key (`jwk`) or key ID (`kid`).
103. func parseSignatureParams(transaction *transaction, headers jws.Headers, _ *jws.Message) error {
104. 	if key, ok := headers.Get(jws.JWKKey); ok {
105. 		jwkKey := key.(jwk.Key)
106. 		transaction.signingKey = jwkKey
107. 	}
108. 	// Get the keyID from the header (not to be confused with the keyID from the embedded key)
109. 	if kid, ok := headers.Get(jws.KeyIDKey); ok {
110. 		transaction.signingKeyID = kid.(string)
111. 	}
112. 	// Check RFC004 3.1 kid and jwk constraints
113. 	if (transaction.signingKey != nil && transaction.signingKeyID != "") || (transaction.signingKey == nil && transaction.signingKeyID == "") {
114. 		return transactionValidationError("either `kid` or `jwk` header must be present (but not both)")
115. 	}
116. 	transaction.signingAlgorithm = headers.Algorithm()
117. 	return nil
118. }
119. 
120. // parseSigningTime parses, validates and sets the transaction signing time.
121. func parseSigningTime(transaction *transaction, headers jws.Headers, _ *jws.Message) error {
122. 	if timeAsInterf, ok := headers.Get(signingTimeHeader); !ok {
123. 		return transactionValidationError(missingHeaderErrFmt, signingTimeHeader)
124. 	} else if timeAsFloat64, ok := timeAsInterf.(float64); !ok {
125. 		return transactionValidationError(invalidHeaderErrFmt, signingTimeHeader)
126. 	} else {
127. 		transaction.signingTime = time.Unix(int64(timeAsFloat64), 0).UTC()
128. 		return nil
129. 	}
130. }
131. 
132. // parseVersion parses, validates and sets the transaction format version.
133. func parseVersion(transaction *transaction, headers jws.Headers, _ *jws.Message) error {
134. 	var version Version
135. 	if versionAsInterf, ok := headers.Get(versionHeader); !ok {
136. 		return transactionValidationError(missingHeaderErrFmt, versionHeader)
137. 	} else if versionAsFloat64, ok := versionAsInterf.(float64); !ok {
138. 		return transactionValidationError(invalidHeaderErrFmt, versionHeader)
139. 	} else if version = Version(versionAsFloat64); version != currentVersion {
140. 		return transactionValidationError("unsupported version: %d", version)
141. 	} else {
142. 		transaction.version = version
143. 		return nil
144. 	}
145. }
