147. // parsePrevious parses, validates and sets the transaction prevs fields.
148. func parsePrevious(transaction *transaction, headers jws.Headers, _ *jws.Message) error {
149. 	if prevsAsInterf, ok := headers.Get(previousHeader); !ok {
150. 		return transactionValidationError(missingHeaderErrFmt, previousHeader)
151. 	} else if prevsAsSlice, ok := prevsAsInterf.([]interface{}); !ok {
152. 		return transactionValidationError(invalidHeaderErrFmt, previousHeader)
153. 	} else {
154. 		for _, prevAsInterf := range prevsAsSlice {
155. 			if prevAsString, ok := prevAsInterf.(string); !ok {
156. 				return transactionValidationError(invalidHeaderErrFmt, previousHeader)
157. 			} else if prev, err := hash.ParseHex(prevAsString); err != nil {
158. 				return transactionValidationError(invalidHeaderErrFmt, previousHeader)
159. 			} else {
160. 				transaction.prevs = append(transaction.prevs, prev)
161. 			}
162. 		}
163. 		return nil
164. 	}
